/* Franklin R31 focused Franklin Assistant, Spanish handoff and community-participation experience */
(() => {
  const SPANISH_CUE=/\b(necesito|ayuda|negocio|clientes|permiso|salud|abogado|vivienda|auto|transporte|adulto mayor|gobierno)\b/i;
  const COMMUNITY_INTENT=/\b(grow my business|business growth|more local customers|market(?:ing)? my business|promote my business|local visibility|business profile|claim my profile|membership plans?|community membership|join franklin navigator|participate in franklin)\b/i;
  const setup=()=>{
    const card=document.querySelector('[data-navigator-bot]'),input=card?.querySelector('[data-navigator-input]'),output=card?.querySelector('[data-navigator-output]'),form=input?.closest('form');
    if(!card||!input||!output||!form||document.querySelector('[data-r27-navigator-dialog]'))return;
    document.querySelectorAll('a[href="/#ask-navigator"]').forEach(a=>{if(/ask navigator/i.test(a.textContent||''))a.textContent='Franklin Assistant'});
    const formLabel=form.querySelector('label[for="navigator-need"]');if(formLabel)formLabel.textContent='Tell Franklin Assistant what you need';
    const submit=form.querySelector('button[type="submit"]');if(submit)submit.textContent='Find my next step';
    const dialog=document.createElement('dialog');dialog.className='r27-navigator-dialog';dialog.dataset.r27NavigatorDialog='true';dialog.setAttribute('aria-labelledby','r27-navigator-title');dialog.innerHTML='<div class="r27-navigator-shell"><div class="r27-navigator-head"><div><div class="eyebrow">Franklin Assistant</div><h2 id="r27-navigator-title">Choose what you want to do now.</h2></div><button class="r27-navigator-close" type="button" aria-label="Close answer">×</button></div><div class="r27-navigator-body" data-r27-navigator-body></div></div>';document.body.append(dialog);
    const body=dialog.querySelector('[data-r27-navigator-body]'),title=dialog.querySelector('#r27-navigator-title'),close=dialog.querySelector('.r27-navigator-close');let returnFocus=input,moving=false;
    const spanish=text=>SPANISH_CUE.test(String(text||''));
    const languageLink=(isEs)=>{const wrap=document.createElement('div');wrap.className='r31-dialog-language';const a=document.createElement('a');a.href=isEs?'/assistant/':'/es/asistente/';a.textContent=isEs?'English':'Español';if(!isEs)a.lang='es';a.addEventListener('click',()=>window.FranklinProductHealth?.record('assistant_spanish_handoff'));wrap.append(a);return wrap;};
    const focusables=()=>[...dialog.querySelectorAll('a[href],button:not([disabled]),textarea,input,select,[tabindex]:not([tabindex="-1"])')].filter(el=>!el.hidden&&el.getAttribute('aria-hidden')!=='true');
    const trapFocus=event=>{if(event.key!=='Tab'||!dialog.hasAttribute('open'))return;const list=focusables();if(!list.length)return;const first=list[0],last=list[list.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}};
    const openDialog=()=>{document.body.classList.add('r27-dialog-open');window.FranklinProductHealth?.record('assistant_dialog_open');typeof dialog.showModal==='function'?dialog.showModal():dialog.setAttribute('open','');requestAnimationFrame(()=>close.focus())};
    const closeDialog=()=>{window.FranklinProductHealth?.record('assistant_dialog_close');if(dialog.open&&typeof dialog.close==='function')dialog.close();else{dialog.removeAttribute('open');document.body.classList.remove('r27-dialog-open');returnFocus?.focus?.()}};
    const addQuestion=text=>{if(!text)return;const p=document.createElement('p');p.className='r27-navigator-question';p.textContent=String(document.documentElement.lang||'').startsWith('es')?`Preguntaste: ${text}`:`You asked: ${text}`;body.append(p)};
    const showCommunityChoices=question=>{moving=true;const isEs=spanish(question);title.textContent=isEs?'sus próximos pasos de negocio y comunidad en Franklin':'Your Franklin business and community next steps';body.replaceChildren();dialog.querySelector('.r31-dialog-language')?.remove();dialog.querySelector('.r27-navigator-head')?.append(languageLink(isEs));addQuestion(question);const section=document.createElement('section');section.className='r27-business-choice';section.innerHTML='<h3>Start with your community presence.</h3><p>Review the profile, see the member version, or use a free planning tool. No payment is requested.</p><div class="r27-business-actions"><a class="button primary" href="/member-profile-preview/">See member options</a><a class="button" href="/claim-profile/">Find or review my profile</a><a class="button" href="/membership-start/">See Community Membership</a><a class="button" href="/local-growth-engine/">Use the free Growth Planner</a></div><p class="r27-business-note">Basic public profiles and factual corrections remain free. Membership supports richer participation and tools; it does not buy ranking, endorsement, leads, customers, sales or guaranteed results.</p>';body.append(section);output.hidden=true;output.replaceChildren();card.classList.remove('has-answer');card.dataset.answerState='dialog';openDialog();moving=false};
    const showGeneratedAnswer=()=>{if(moving||output.hidden||!String(output.textContent||'').trim())return;moving=true;const isEs=String(document.documentElement.lang||'').startsWith('es');title.textContent=isEs?'Estos son sus próximos pasos en Franklin.':'Here are your Franklin next steps.';body.replaceChildren();dialog.querySelector('.r31-dialog-language')?.remove();dialog.querySelector('.r27-navigator-head')?.append(languageLink(isEs));addQuestion(input.value.trim());for(const node of [...output.childNodes])body.append(node);
      const next=document.createElement('div');next.className='r30-dialog-next';next.innerHTML=isEs?'<p><strong>¿tiene más de una necesidad?</strong> Crea un plan privado en este dispositivo para necesidades relacionadas en Franklin.</p><a class="button" href="/situation-planner/">Crear un plan para necesidades conectadas</a>':'<p><strong>More than one need?</strong> Build one private, device-only plan across connected Franklin needs.</p><a class="button" href="/situation-planner/">Build one plan for connected needs</a>';body.append(next);output.hidden=true;output.replaceChildren();card.classList.remove('has-answer');card.dataset.answerState='dialog';openDialog();moving=false};
    form.addEventListener('submit',()=>{returnFocus=input},true);
    card.addEventListener('click',event=>{const trigger=event.target instanceof Element?event.target.closest('button,a'):null;if(trigger)returnFocus=trigger},true);
    window.addEventListener('franklinlanguagechange',()=>{if(dialog.open&&input.value.trim())window.FranklinR38Assistant?.render(output,input.value)});
    const publicSection=document.querySelector('.r24-business-section');if(publicSection){const heading=publicSection.querySelector('h2'),paragraph=publicSection.querySelector('p'),links=publicSection.querySelectorAll('.actions a');if(heading)heading.textContent='Participate more fully in the Franklin community.';if(paragraph)paragraph.textContent='Review your public profile, see the richer member version, and use free local planning tools before deciding whether membership fits.';if(links[0]){links[0].href='/member-profile-preview/';links[0].textContent='See member options'}if(links[1]){links[1].href='/membership-start/';links[1].textContent='See Community Membership'}}
    const observer=new MutationObserver(()=>queueMicrotask(showGeneratedAnswer));observer.observe(output,{attributes:true,attributeFilter:['hidden'],childList:true,subtree:true,characterData:true});dialog.addEventListener('keydown',trapFocus);close.addEventListener('click',closeDialog);dialog.addEventListener('click',e=>{if(e.target===dialog)closeDialog()});dialog.addEventListener('close',()=>{document.body.classList.remove('r27-dialog-open');if(returnFocus instanceof HTMLElement)requestAnimationFrame(()=>returnFocus.focus())});
  };
  document.readyState==='loading'?document.addEventListener('DOMContentLoaded',setup,{once:true}):setup();
})();
